84	  );
85	}
86	
87	/** Optional second secret part (e.g. key-pair passphrase) — rides `composeSecret`.
88	 * The form's `requiredMark="optional"` renders the (optional) marker.
89	 * `preserve={false}` drops the value when the field unmounts (auth-mode switch,
90	 * modal close) so a stale passphrase can never wrap another mode's secret. */
91	export function PassphraseField({ label }: { label: string }) {
92	  return (
93	    <Form.Item
94	      name="secretPassphrase"
95	      label={label}
96	      preserve={false}
97	      extra="Only for passphrase-protected keys; leave blank for an unencrypted key."
98	    >
99	      <Input.Password autoComplete="off" />
100	    </Form.Item>
101	  );
102	}
103	
104	export function ConnectionTypeFields({
105	  type,
106	  form,
107	  showSecret = true,
108	}: {
109	  type: ConnectionType;
110	  form: FormInstance;
111	  /** Edit mode omits the secret — credential rotation is the Re-auth flow. */
112	  showSecret?: boolean;
113	}) {
114	  const spec = CONNECTION_FORM_SPECS[type];
115	  const authType = Form.useWatch(['config', 'auth_type'], form) as string | undefined;
116	  const activeAuth = activeAuthOption(type, { auth_type: authType });
117	
118	  return (
119	    <>
120	      {spec.textFields.map((f) => (
121	        <ConfigTextField
122	          key={f.name}
123	          field={f}
124	          forceRequired={activeAuth?.requiredFields?.includes(f.name)}
125	        />
126	      ))}
127	
128	      {spec.auth && (
129	        <Form.Item name={['config', 'auth_type']} label="Auth type" rules={requiredRule}>
130	          <Select options={spec.auth.map((a) => ({ value: a.value, label: a.label }))} />
131	        </Form.Item>
132	      )}
133	
134	      {activeAuth?.extraField && <ConfigTextField field={activeAuth.extraField} />}
135	
136	      {showSecret &&
137	        (activeAuth ? (
138	          <>
139	            <SecretField label={activeAuth.secretLabel} multiline={activeAuth.multilineSecret} />
140	            {activeAuth.passphraseLabel && <PassphraseField label={activeAuth.passphraseLabel} />}
141	          </>
142	        ) : (
143	          spec.secretLabel && (
144	            <SecretField label={spec.secretLabel} optional={spec.optionalSecret} />
145	          )
146	        ))}
147	    </>
148	  );
149	}

